(()=>{function sync(){document.querySelectorAll('[data-calc-choice]').forEach(b=>b.setAttribute('aria-pressed',String(Number(document.getElementById(b.dataset.calcChoice).value)===Number(b.dataset.value))));for(const [id,unit] of [['calc-flow','mL/min'],['calc-hours-day','hours/day']])document.getElementById(id+'-readout').textContent=Number(document.getElementById(id).value)+(id==='calc-flow'?' mL/min':' hours/day');}document.querySelectorAll('[data-calc-choice]').forEach(b=>b.addEventListener('click',()=>{const input=document.getElementById(b.dataset.calcChoice);input.value=b.dataset.value;input.dispatchEvent(new Event('input',{bubbles:true}));}));document.addEventListener('resolve-model',sync);sync();})();